"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["39305"],{82713(e){e.exports=JSON.parse('{"id":13546,"title":"1","description":"Create a luxurious, high-converting website from scratch for Sunset Coffee Company (local coffee shop in Sandy, UT). The site must communicate warm, community-focused hospitality, scenic mountain/patio vibes, and convert visitors into in-store guests, online orders, and loyalty/newsletter signups.\\nBusiness facts (use these)\\n\\nName: Sunset Coffee Company\\nLocation: Sandy, UT (High Point Center) \u2014 scenic mountain views, patio\\nHours: open late (example: closes 12 AM)\\nPrice: $1\u201310 per person\\nPhone: +1 801-233-9151\\nAttributes: relaxed hangout, free Wi\u2011Fi, patio, scenic sunset/valley views, LGBTQ+ friendly\\nPopular items: Cold Brew, Cappuccino, Caf\xe9 Au Lait, Mary Monroe drink (regular & frozen), Cookies & Cream, Lemon Roll, Cortado, Sweet Tea, Cider, Gift Basket\\nTone from reviews: friendly, community-oriented, kind staff, trendy/cool, great atmosphere, highly recommended\\nTarget customers & conversion goals (assume)\\n\\nLocal residents and visitors, 18\u201345, coffee lovers, remote workers, social groups\\nPrimary conversions: visit in-person (map/directions), place takeaway/order online, join loyalty/newsletter, book patio events or buy gift baskets\\nDeliverables\\n\\nFull brand direction (logo suggestions, color palette, typography, imagery style, iconography, moodboard)\\nComplete sitemap and content plan\\nHigh-fidelity responsive UI mockups (desktop, tablet, mobile) + Figma-ready assets\\nProduction-ready HTML/CSS (clean, semantic, accessible) + brief JS for interactions; components as reusable snippets\\nCMS-ready templates (recommend Webflow or similar) with content placeholders\\nSEO/meta tag plan for homepage, menu, about, contact, and gift basket pages\\nCRO elements (CTA copy, banner, modal flows, urgency/timers, social proof components, review snippets)\\nAccessibility, performance, and analytics checklist\\nDesign & brand direction (explicit)\\n\\nVibe: luxurious-warm + relaxed neighborhood hangout. Think refined rustic: matte bronze accents, deep sunset gradient (warm orange \u2192 rose \u2192 deep plum), cream neutrals, tactile textures (linen, wood), soft shadows.\\nPalette: primary (Sunset Gradient), secondary (warm cream, deep plum), accent (matte bronze, sage green). Provide HEXs.\\nTypography: elegant display (serif or modern serif) for headings + highly readable sans for body. Include example fonts (Google Fonts).\\nImagery: large hero with sunset/patio valley view at golden hour, candid shots of friendly staff and smiling customers, close-ups of signature drinks and pastries, overhead menu flatlays. Photo mood: warm, shallow depth of field, bokeh highlights, premium retouch.\\nUI elements: glassmorphism cards with soft borders, rounded buttons with bronze gradient, subtle micro-animations on hover, sticky CTA bar for ordering/phone directions.\\nPages & priority content (structure)\\n\\nHomepage (hero, 3\u2011line value props, CTA: Order / Visit / Menu, social proof bar with aggregated rating 4.6/5 + short review quote, featured drinks carousel, loyalty signup block, footer with hours & map)\\nHero example headline: \\"Sunset views. Expert coffee. Your new favorite neighborhood hangout.\\"\\nSubhead: \\"Scenic patio. Thoughtful service. Drinks & pastries crafted for moments that matter.\\"\\nMenu (filterable by hot, cold, pastries, signature drinks, seasonal; prominent online-order buttons; downloadable PDF)\\nAbout (story, mission: community + hospitality, staff highlights, LGBTQ+ friendly statement, photo of patio at sunset)\\nLocations & Hours (interactive map, large CTA: Get directions, phone call link, parking info)\\nOrder/Preorder (integrate or mock Webflow/Shopify/Toast/Chownow flow; mobile-first checkout)\\nGift Baskets & Merch (product pages with high-res photos, add-to-cart, local delivery/pickup options)\\nEvents & Catering (patio bookings, private events form)\\nGallery / Instagram feed\\nContact & Careers (contact form, hire form with perks)\\nBlog / News (seasonal drinks, community stories)\\nCopy & tone guidance (examples)\\n\\nMain CTA: \\"Order Online\\" / \\"Visit Our Patio\\"\\nMicrocopy: \u201COpen late \u2014 perfect for after-work catchups.\u201D; \u201CWe\u2019re LGBTQ+ friendly \u2014 everyone\u2019s welcome.\u201D; Button: \u201CSee today\u2019s menu\u201D\\nReview snippet examples to surface: \u201CThe staff is super friendly \u2014 makes you feel welcome.\u201D; \u201CThey gave me a drink on the house when I needed it. Incredible kindness.\u201D\\nConversion components (specs)\\n\\nPersistent top bar: hours + CTA \\"Order\\" + phone tap\\nSticky bottom CTA on mobile: \\"Order \u2022 Directions \u2022 Call\\"\\nHomepage social-proof module: aggregated rating + 2 rotating 5\u2011star review highlights (pull from provided reviews)\\nLoyalty modal: 10% off first signup; email + phone (SMS opt\u2011in)\\nExit-intent overlay: offer limited-time discount for pickup orders\\nUrgency: show live busy indicator (\u201CNot too busy / moderate / busy\u201D) mock based on popular times\\nEvent booking form with calendar, deposit option\\nTechnical & SEO\\n\\nFast-loading: optimized images (AVIF/WebP), lazy-load gallery, critical CSS inline\\nAccessibility: semantic HTML, keyboard nav, alt text for all images, color contrast checks\\nSchema.org: LocalBusiness, Menu, Product (gift baskets), AggregateRating with 4.6 stars\\nMeta: recommended title/meta description examples for key pages\\nAnalytics: setup GTM, GA4, conversion events (order, signup, click-to-call, directions)\\nAssets & Handoff\\n\\nProvide Figma file + exported PNG/JPEG/WebP images + SVG icons + CSS variables + HTML templates\\nInclude README with deployment steps (Webflow/Netlify), third-party integrations (ordering provider, Mailchimp), and estimated timelines (design 1 week, dev 2 weeks)\\nConstraints & assumptions\\n\\nLocal pickup & in-store focus; no large e-commerce catalog\\nBudget-conscious but premium finish; prioritize mobile UX\\nUse colors, photos, and microcopy that reinforce warmth and human hospitality\\nExecution instructions for Claude\\n\\nProduce: (A) a one-page creative brief with brand palette, fonts, hero copy, and three sample hero images descriptions; (B) structured sitemap with page-by-page content outlines; (C) exact HTML/CSS for a responsive homepage + menu page (clean, tested, accessible) ready to paste into Webflow or static host; (D) Figma-ready spec (JSON-style frame descriptions) and export-ready asset list; (E) SEO meta tags and JSON-LD schema for LocalBusiness and Menu.\\nPrioritize responsive mobile-first code and fast performance. Show live examples of copy in context.\\nOutput clearly labeled sections so a developer/designer can implement directly.\\nUse the review excerpts and attributes above to shape copy and social proof throughout. Deliver code and design that feel luxurious yet warm, and maximize conversions for visits, orders, and loyalty signups.\\n\\nIf you want, start by producing the one-page creative brief, then the responsive homepage HTML/CSS.\\n\\nWould you like the brief now or the full homepage code first?","owner":"anesavm11","upvotes":1,"downvotes":0,"upvoteDifference":1,"updatedAt":"2026-06-01T01:42:06.742Z"}')}}]);